import{_ as u,a0 as r,w as i,s as l,ao as e,I as n,x as p,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const k=JSON.parse('{"title":"修復無法添加 PPA：“This PPA does not support jammy” 錯誤 | LCTT x X-CMD","titleTemplate":false,"description":"修復無法添加 PPA：“This PPA does not support jammy” 錯誤 | LCTT (202310) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"修復無法添加 PPA：“This PPA does not support jammy” 錯誤 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"修復無法添加 PPA：“This PPA does not support jammy” 錯誤 | LCTT (202310) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202310/20230919 Fixing Cannot add PPA- --This PPA does not support jammy-- Error","title":"修復無法添加 PPA：“This PPA does not support jammy” 錯誤","tag":"202310","desc":""},"relativePath":"202310/20230919 Fixing Cannot add PPA- --This PPA does not support jammy-- Error.md","filePath":"[post].md"}'),d={name:"202310/20230919 Fixing Cannot add PPA- --This PPA does not support jammy-- Error.md"};function P(m,t,b,A,f,g){const s=r("Link");return i(),l("div",null,[t[30]||(t[30]=e('<h1 id="修復無法添加-ppa-this-ppa-does-not-support-jammy-錯誤" tabindex="-1">修復無法添加 PPA：“This PPA does not support jammy” 錯誤 <a class="header-anchor" href="#修復無法添加-ppa-this-ppa-does-not-support-jammy-錯誤" aria-label="Permalink to “修復無法添加 PPA：“This PPA does not support jammy” 錯誤”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202310/02/112157nf11fpwhwa4u1hvf.jpg" alt=""></p><blockquote><p>嘗試添加一個 PPA，卻在 Ubuntu 中收到 “無法添加 PPA： 此 PPA 不支持 xyz” 的錯誤？下面是解決這一錯誤的方法。</p></blockquote><p>這是一個場景。你正在嘗試使用 PPA 在 Ubuntu 中安裝軟件。</p><p>你使用 <code>sudo add-apt-repository</code> 添加 PPA 倉庫，當它更新包緩存時，會出現錯誤：</p><blockquote><p>Cannot add PPA: &quot;This PPA does not support <em>xyz</em></p></blockquote>',6)),n("p",null,[t[1]||(t[1]=p("其中 “xyz” 是 ",-1)),o(s,{href:"https://itsfoss.com/how-to-know-ubuntu-unity-version/"},{default:a(()=>[...t[0]||(t[0]=[p("你正在使用的 Ubuntu 版本的代號",-1)])]),_:1}),t[2]||(t[2]=p("。",-1))]),t[31]||(t[31]=e('<p>📋 這就是發生這種情況的原因以及你可以採取的措施：</p><ul><li>PPA 不適用於你正在使用的 Ubuntu 版本</li><li>你應該尋找其他來源來安裝該應用</li><li>如果絕望了，你可以從 PPA 網頁下載 .deb 文件</li></ul><p>我將詳細討論以上所有內容。</p><h3 id="檢查-ppa-是否適用於你的-ubuntu-版本" tabindex="-1">檢查 PPA 是否適用於你的 Ubuntu 版本 <a class="header-anchor" href="#檢查-ppa-是否適用於你的-ubuntu-版本" aria-label="Permalink to “檢查 PPA 是否適用於你的 Ubuntu 版本”">​</a></h3><p>首先，在終端中使用以下命令獲取 Ubuntu 版本和代號的詳細信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lsb_release -a</span></span></code></pre></div><p>輸出將包含詳細信息：</p><p><img src="https://itsfoss.com/content/images/2023/09/ubuntu-version-details.png" alt="Here, I am using Ubuntu version 23.04 that case codename lunar"></p><p>現在，訪問託管所有 PPA 的 Ubuntu 的 Launchpad 網站：</p>',9)),n("blockquote",null,[n("p",null,[n("strong",null,[o(s,{href:"https://launchpad.net/ubuntu/+ppas"},{default:a(()=>[...t[3]||(t[3]=[p("進入 Launchpad PPA",-1)])]),_:1})])])]),t[32]||(t[32]=e('<p>在這裏，查找困擾你的 PPA。為此，你必須使用 PPA 維護者的名字。</p><p>例如，如果 <code>ppa:jstaf/onedriver</code> 造成問題，請搜索維護者 <code>jstaf</code>。</p><p><img src="https://itsfoss.com/content/images/2023/09/search-for-ppa-launchpad.png" alt="Enter the PPA&#39;s maintainer name and search for it"></p><p>一名維護者可能擁有多個軟件倉庫。單擊你要安裝的那個。</p><p>在裏，你應該在 “<ruby>發佈於<rt>Published in</rt></ruby>” 旁邊的下拉按鈕選擇 “<ruby>所有系列<rt>Any Series</rt></ruby>”。</p><p><img src="https://itsfoss.com/content/images/2023/09/check-ppa-supported-version.png" alt="Click on Any series dropdown button to see the supported Ubuntu versions"></p><p>檢查你是否看到你正在使用的 Ubuntu 版本的代號。如果不存在，那麼此 PPA 不適用於你的 Ubuntu 版本。</p><h3 id="如果-ppa-不支持你的-ubuntu-版本-你該怎麼辦" tabindex="-1">如果 PPA 不支持你的 Ubuntu 版本，你該怎麼辦 <a class="header-anchor" href="#如果-ppa-不支持你的-ubuntu-版本-你該怎麼辦" aria-label="Permalink to “如果 PPA 不支持你的 Ubuntu 版本，你該怎麼辦”">​</a></h3><p>你會看到，開發人員（或維護人員）創建一個倉庫並使該軟件可用於他們正在使用的 Ubuntu 版本。</p><p>隨着時間的推移，Ubuntu 發佈了更新的版本。現在，一位活躍的維護者將發佈新 Ubuntu 版本的軟件。但情況並非總是如此。如果維護者不再活躍，那麼將不會更新。像你這樣嘗試遵循教程説明的人將會看到此錯誤。</p><p>現在，你有兩個選擇：</p><h4 id="選項-1-在其他地方尋找該軟件" tabindex="-1">選項 1：在其他地方尋找該軟件 <a class="header-anchor" href="#選項-1-在其他地方尋找該軟件" aria-label="Permalink to “選項 1：在其他地方尋找該軟件”">​</a></h4><p>這裏有幾種可能性。</p><p><strong>新版 Ubuntu 可能也可以通過其他 PPA 獲得相同的軟件。請在 Launchpad 網站或互聯網上查找。</strong></p><p>這是怎麼發生的？許多原始軟件開發人員只是發佈源代碼，因此一些志願者創建 Debian 軟件包並從 Launchpad 分發它，以便像你這樣的 Ubuntu 用户可以輕鬆安裝該軟件。不止一名志願者可以為同一軟件創建自己的個人包存檔（PPA）。你應該使用活躍的一個。</p>',15)),n("p",null,[t[5]||(t[5]=p("例如，如果我查找 ",-1)),t[6]||(t[6]=n("code",null,"onedriver",-1)),t[7]||(t[7]=p(" 包，我可以看到它可能在另一個名為 ",-1)),o(s,{href:"https://launchpad.net/~remiariro/+archive/ubuntu/misc"},{default:a(()=>[...t[4]||(t[4]=[p("Ubuntu deployment",-1)])]),_:1}),t[8]||(t[8]=p(" 的 PPA 中可用。",-1))]),t[33]||(t[33]=n("p",null,[n("img",{src:"https://itsfoss.com/content/images/2023/09/search-ppa.png",alt:""})],-1)),t[34]||(t[34]=n("p",null,[n("strong",null,"另一個方式是查看該包是否以其他格式提供，例如 Snap、Flatpak、AppImage。")],-1)),n("ul",null,[n("li",null,[o(s,{href:"https://snapcraft.io/store"},{default:a(()=>[...t[9]||(t[9]=[p("檢查 Snap 商店",-1)])]),_:1})]),n("li",null,[o(s,{href:"https://flathub.org/"},{default:a(()=>[...t[10]||(t[10]=[p("檢查 Flatpak 包",-1)])]),_:1})]),n("li",null,[o(s,{href:"https://www.appimagehub.com/"},{default:a(()=>[...t[11]||(t[11]=[p("檢查 AppImages",-1)])]),_:1})])]),t[35]||(t[35]=e('<p>在極少數情況下，該軟件可能已經在 Ubuntu 倉庫中可用。</p><p>為此，你必須是一個聰明的用户並在互聯網上進行搜索。如果你找到其他包格式，那就太好了。否則，下一步就是絕望。</p><h4 id="選項-2-從-ppa-下載-deb-文件" tabindex="-1">選項 2：從 PPA 下載 deb 文件 <a class="header-anchor" href="#選項-2-從-ppa-下載-deb-文件" aria-label="Permalink to “選項 2：從 PPA 下載 deb 文件”">​</a></h4><p>PPA 倉庫為你提供 Debian 軟件包。添加倉庫後，你還可以直接通過系統更新獲得更新（如果有）。</p><p>如果你的 Ubuntu 版本的 PPA 沒有更新，並且你在其他地方找不到該軟件，你可以嘗試從 PPA Launchpad 頁面下載 deb 軟件包。</p><p><img src="https://itsfoss.com/content/images/2023/09/ppa-package-details.png" alt=""></p><p>在包詳細信息頁面上，單擊展開符號並查找 deb 文件。除非你使用類似樹莓派的主板，否則你應該選擇 amd64。</p><p><img src="https://itsfoss.com/content/images/2023/09/download-deb-from-ppa.png" alt="Download deb package from PPA"></p><blockquote><p>🚧 如果軟件太舊，下載的 deb 包可能會因為依賴問題而無法安裝成功。此外，你將不會獲得已安裝軟件包的更新（如果已安裝）。不過，這個方法還是值得一試。</p></blockquote><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>儘管 Canonical 在大力推動 Snap 打包，PPA 仍然是用户在 Ubuntu 中安裝第三方應用的最愛。</p>',11)),n("p",null,[t[13]||(t[13]=p("但 PPA 也有其自身的麻煩，而不能添加 PPA 錯誤就是其中之一。同樣的問題還會導致 “",-1)),o(s,{href:"https://itsfoss.com/repository-does-not-have-release-file-error-ubuntu/"},{default:a(()=>[...t[12]||(t[12]=[p("倉庫沒有發佈文件",-1)])]),_:1}),t[14]||(t[14]=p("” 錯誤。",-1))]),t[36]||(t[36]=n("p",null,"我希望現在這個問題更加清楚了。如果你仍有疑問，請告訴我。",-1)),t[37]||(t[37]=n("p",null,[n("em",null,"（題圖：MJ/d1013502-d518-4bc8-896c-d8dddd15ae22）")],-1)),t[38]||(t[38]=n("hr",null,null,-1)),n("p",null,[t[16]||(t[16]=p("via: ",-1)),o(s,{href:"https://itsfoss.com/cannot-add-ppa-error/"},{default:a(()=>[...t[15]||(t[15]=[p("https://itsfoss.com/cannot-add-ppa-error/",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=p("作者：",-1)),o(s,{href:"https://itsfoss.com/author/abhishek/"},{default:a(()=>[...t[17]||(t[17]=[p("Abhishek Prakash",-1)])]),_:1}),t[22]||(t[22]=p(" 選題：",-1)),o(s,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[18]||(t[18]=[p("lujun9972",-1)])]),_:1}),t[23]||(t[23]=p(" 譯者：",-1)),o(s,{href:"https://github.com/geekpi"},{default:a(()=>[...t[19]||(t[19]=[p("geekpi",-1)])]),_:1}),t[24]||(t[24]=p(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:a(()=>[...t[20]||(t[20]=[p("wxy",-1)])]),_:1})]),n("p",null,[t[27]||(t[27]=p("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[25]||(t[25]=[p("LCTT",-1)])]),_:1}),t[28]||(t[28]=p(" 原創編譯，",-1)),o(s,{href:"https://linux.cn/"},{default:a(()=>[...t[26]||(t[26]=[p("Linux中國",-1)])]),_:1}),t[29]||(t[29]=p(" 榮譽推出",-1))])])}con